var config = [
    "https://boat.fulhexov.com",
    "https://blanket.fulhexov.com",
    "https://address.fulhexov.com",
    ""];
if (!String(source.getVariable())) {
    const defaultConfig = ["","","",""];
    source.setVariable(JSON.stringify(defaultConfig));
}
function setMainLink(lineIndex) {
    try {
        let stored = source.getVariable();
        if (!stored) {
            java.toast("请先获取线路");
            return;
        }
        let dataArray = JSON.parse(stored);
        if (lineIndex < 0 || lineIndex >= config.length) {
            java.toast("无效的线路选择");
            return;
        }
        const newValue = config[lineIndex];
        dataArray[0] = newValue;
        source.setVariable(JSON.stringify(dataArray));
        if (newValue === "") {
            java.toast("链接已清除");
        } else {
            java.toast(`已设置为线路${lineIndex + 1}\n${newValue}\n刷新生效`);
        }
    } catch (e) {
        java.toast('操作失败: ' + e.message);
    }
}
function showCurrentInterface() {
    try {
        let storedData = source.getVariable();
        if (!storedData) {
            java.toast("未设置当前接口");
            return;
        }
        let dataArray = JSON.parse(storedData);
        let currentLink = dataArray[0];
        if (currentLink) {
            java.toast(`当前接口:\n${currentLink}`);
        } else {
            java.toast("接口未设置");
        }
    } catch (e) {
        java.toast("读取接口出错: " + e.message);
    }
}

