	 java.toast(`\n当前域名:【${x}】\n${getUrl()}`)
}

//设置域名
var A = (x) => {
  let v = String(source.getVariable()).split(",");
  v[1] = x;
	 source.setVariable(v.join(","));
	 java.toast(`\n当前域名:【${v[1]}】\n${getUrl()}`)
}

